import { useState } from 'react';
import NotificationList from './NotificationList';
import { ToastMessage } from './types';

const App = () => {
  const [messages, setMessages] = useState<ToastMessage[]>([]);
  const [showToast, setShowToast] = useState(false);

  const handleSuccess = () => {
    addToast('Operation successful!', 'success');
  };

  const handleWarning = () => {
    addToast('This is a warning!', 'warning');
  };

  const handleError = () => {
    addToast('An error occurred!', 'error');
  };

  const addToast = (message: string, type: 'success' | 'warning' | 'error') => {
    const newMessage: ToastMessage = {
      id: Date.now(),
      message,
      type,
      timestamp: new Date().toISOString(),
    };
    setMessages((prev) => [newMessage, ...prev.slice(0, 4)]); // Keep only last 5
    setShowToast(true);
    setTimeout(() => setShowToast(false), 3000);
  };

  const clearAll = () => {
    setMessages([]);
  };

  return (
    <div className="min-h-screen bg-gray-50 flex flex-col items-center justify-start p-6 font-sans">
      <div className="w-full max-w-lg bg-white rounded-lg shadow-md p-6 space-y-6">
        <h1 className="text-2xl font-bold text-center text-gray-800">Notification Center</h1>

        <div className="flex flex-wrap gap-3 justify-center">
          <button
            onClick={handleSuccess}
            className="px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600 transition-colors"
          >
            Success
          </button>
          <button
            onClick={handleWarning}
            className="px-4 py- 2 bg-yellow-500 text-white rounded-md hover:bg-yellow-600 transition-colors"
          >
            Warning
          </button>
          <button
            onClick={handleError}
            className="px-4 py-2 bg-red-500 text-white rounded-md hover:bg-red-600 transition-colors"
          >
            Error
          </button>
        </div>

        <NotificationList messages={messages} onClear={clearAll} />

        {showToast && (
          <div className="fixed top-4 right-4 bg-blue-500 text-white px-4 py-2 rounded-md shadow-lg animate-pulse">
            Toast message visible
          </div>
        )}
      </div>
    </div>
  );
};

export default App;
```

